package br.gov.dere.application.mock;
import br.gov.dere.application.d1001.D1001XmlGenerator; import br.gov.dere.domain.*; import br.gov.dere.domain.contributor.D1001; import br.gov.dere.integration.signature.*; import br.gov.dere.integration.xml.*; import br.gov.dere.persistence.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class LocalDereFlowService { private final DereEventRepository events; private final DereBatchRepository batches; private final DereEventErrorRepository errors; private final DereValidationAuditRepository audits; private final D1001XmlGenerator generator=new D1001XmlGenerator(); private final DereXmlSigner signer=new DereXmlSigner(); private final DereXmlSignatureVerifier verifier=new DereXmlSignatureVerifier();
 public LocalDereFlowService(DereEventRepository e,DereBatchRepository b,DereEventErrorRepository er,DereValidationAuditRepository a){events=e;batches=b;errors=er;audits=a;}
 @Transactional public FlowResult submit(D1001 d,Long userId,Long entityId){try {String unsigned=generator.generate(d); validate(unsigned,"evtInfoContrib-v1_0_1.xsd"); var event=new DereEventEntity("D-1001",d.id(),"restricted-production","nota_2026_001",unsigned);events.save(event);var ks=LocalTestCertificate.create();String signed=signer.sign(unsigned,ks,"changeit".toCharArray(),"dere-test");if(!verifier.verify(signed,ks,"dere-test"))throw new IllegalStateException("Assinatura XMLDSig inválida");validate(signed,"evtInfoContrib-v1_0_1.xsd"); event.signed(signed);events.save(event);String lote=new DereBatchBuilder().build(d.cnpjRoot(),List.of(signed));validate(lote,"envioLoteDere-v1_0_1.xsd");audits.save(new DereValidationAuditEntity(userId,entityId,"SEND","D-1001",true,"",lote,null));var batch=new DereBatchEntity(lote);batches.save(batch);String protocol="MOCK-"+UUID.randomUUID();batch.received(protocol);batches.save(batch);return new FlowResult(batch.getId(),protocol,event.getEventIdentifier(),EventStatus.PROCESSING,lote); }catch(Exception ex){audits.save(new DereValidationAuditEntity(userId,entityId,"SEND","D-1001",false,ex.getMessage(),null,null));throw new IllegalStateException("Falha no fluxo local DeRE",ex);} }
 @Transactional public FlowResult query(Long batchId){var b=batches.findById(batchId).orElseThrow();b.completed(EventStatus.ACCEPTED,"<retorno><protocolo>"+b.getProtocol()+"</protocolo><situacao>ACEITO</situacao><recibo>REC-"+b.getId()+"</recibo></retorno>");batches.save(b);var event=events.findAll().stream().filter(e->b.getRequestXml().contains(e.getEventIdentifier())).findFirst().orElseThrow();event.processed(EventStatus.ACCEPTED,"REC-"+b.getId());events.save(event);return new FlowResult(b.getId(),b.getProtocol(),event.getEventIdentifier(),EventStatus.ACCEPTED,b.getRequestXml());}
 private void validate(String xml,String file)throws Exception{var url=getClass().getResource("/dere/schemas/nota_2026_001/xsd/"+file);if(url==null)throw new IllegalStateException("XSD não encontrado: "+file);XmlSupport.validate(xml,url);}
 public record FlowResult(Long batchId,String protocol,String eventId,EventStatus status,String xml){}
}
